function listeningLines(text){return text.split(/\n+/).filter(x=>x.trim()).flatMap(line=>{const m=line.match(/^\s*([MW]|男|女)\s*[:：]\s*(.*)/i),speaker=m?m[1].toUpperCase():'',words=m?m[2]:line.trim();return words.split(/(?<=[!?])\s+|(?<=[.])\s+(?=[A-Z])(?![A-Z]\.)/).filter(Boolean).map(text=>({...blankSegment(),speaker,text}))})}
