  if(listeningRevisionCore(draft)===listeningRevisionCore(recordingOriginals.get(draft.materialId).draft)||!listeningRevisionNeedsConfirmation(affected)){saveRecordingRevision(mode);return}
  openDialog(mode==='update'?'确认保存修改':'确认硬伤修正',`<p>将同步修正当前共用版本，以下书籍会受到影响。已发布书籍需更新发布后生效。</p><div class="table-scroll"><table class="table"><thead><tr><th>书籍 ID</th><th>书籍名称</th><th>版本</th><th>发布状态</th></tr></thead><tbody>${affected.map(b=>`<tr><td>${esc(bookValue(b,'bookId'))}</td><td>${esc(b.name)}</td><td>${esc(bookValue(b,'version'))}</td><td>${esc(bookPublicationStatus(b))}</td></tr>`).join('')||'<tr><td colspan="4">暂无引用书籍</td></tr>'}</tbody></table></div>`,'<button class="btn" data-close>取消</button><button class="btn primary" id="confirm-recording-correction">确认同步修正</button>');
