 const choices=listeningTagChoices();
 const select=(label,key,value,attr,secondary='')=>`<label class="field"><span>${key!=='topics'?'<span class="lc-required" aria-hidden="true">*</span> ':''}${label}</span>${['topics','examPoints'].includes(key)?listeningHierarchySelect(key,value,key==='topics'?draft.topicSecondary:secondary,attr,key==='topics'?'id="lc-topic-secondary"':'data-qfield="examPointSecondary"'):`<select class="input" aria-required="true" ${attr}>${key==='abilities'?listeningDictionaryOptions(key,choices[key],value):opts(choices[key].map(v=>[v,v]),value,'请选择')}</select>`}</label>`;
