 return `<div class="lc-columns"><section class="lc-source"><textarea class="input lc-paste" id="lc-raw" aria-label="统一录入" placeholder="粘贴录音稿、小题、答案、解析及标签">${esc(draft.raw)}</textarea></section><div class="lc-recognize-column"><button class="btn primary" id="lc-recognize"><svg aria-hidden="true" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12h16M13 5l7 7-7 7"/></svg><span>识别</span></button></div><section class="lc-result">${draft.questions.length?`<div class="lc-transcript-heading"><label for="lc-text"><span class="lc-required" aria-hidden="true">*</span> 录音稿</label>${batch?select('题型','questionType',draft.questionType,'id="lc-record-type"'):''}${select('话题','topics',draft.topics,'id="lc-topics"')}</div><textarea class="input lc-transcript" id="lc-text" required aria-required="true">${esc(draft.text)}</textarea>`+draft.questions.map((q,i)=>`<article class="lc-question-card" data-question="${i}"><div class="lc-question-heading"><h4>小题 ${i+1}</h4><div class="lc-tags">${batch?'':select('题型','questionType',q.questionType,'data-qfield="questionType"')}${select('考点','examPoints',q.examPoints,'data-qfield="examPoints"',q.examPointSecondary)}${select('能力','abilities',q.abilities,'data-qfield="abilities"')}</div></div><div class="lc-table-scroll"><table class="lc-question-table"><colgroup><col class="lc-col-label"><col><col class="lc-col-answer"></colgroup>${batch?'':`<thead><tr><th scope="col" aria-label="项目"></th><th scope="col"><span class="lc-required" aria-hidden="true">*</span> 试题内容</th><th scope="col"><span class="lc-required" aria-hidden="true">*</span> 答案</th></tr></thead>`}<tbody><tr><th scope="row">题干</th><td>${cell('题干',q.text,'data-qfield="text" required aria-required="true"')}</td><td></td></tr>${q.options.map((o,j)=>`<tr class="lc-option-row ${q.answerKey===o.key?'is-answer-row':''}"><th scope="row">${esc(o.key)}</th><td>${cell('选项'+o.key,o.text,`data-option="${j}" required aria-required="true"`)}</td><td><button type="button" class="lc-answer-button ${q.answerKey===o.key?'is-answer':''}" data-set-answer="${esc(o.key)}" aria-pressed="${q.answerKey===o.key}">${q.answerKey===o.key?'已设为答案':'设为答案'}</button></td></tr>`).join('')}</tbody></table></div><label class="lc-analysis"><span>答案解析</span><textarea class="input" rows="1" data-qfield="analysisText">${esc(q.analysisText||'')}</textarea></label></article>`).join(''):'<div class="lc-empty">识别后在此编辑</div>'}</section></div>`
